public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, result, new ArrayList<>(), 0);
    return result;
}

private void backtrack(int[] nums, List<List<Integer>> result, List<Integer> current, int begin) {
    if (begin == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = begin; i < nums.length; i++) {
        current.add(nums[i]);
        backtrack(nums, result, current, i + 1);
        current.remove(current.size() - 1);
    }
}

public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring length to 0
    int largestSubstringLength = 0;
    // Iterate over each string in the list
    for (String string : strings) {
        // Get the length of the string
        int stringLength = string.length();
        // Check if the string is the largest substring so far
        if (stringLength > largestSubstringLength) {
            // If the string is longer than the largest substring so far, update the largest substring length
            largestSubstringLength = stringLength;
        }
        // Check if the inverse of the string is the largest substring so far
        if (stringLength > largestSubstringLength) {
            // If the inverse of the string is longer than the largest substring so far, update the largest substring length
            largestSubstringLength = stringLength;
        }
    }
    return largestSubstringLength;
}

