public static int maxRegions(int N) {
    if (N == 1) {
        return 2;
    } else if (N == 2) {
        return 8;
    } else {
        // Use the recursive formula to calculate the maximum number of regions
        int maxRegions = N * (N - 1) / 2;
        return maxRegions;
    }
}

public static int maxRegions(int N) {
    // Calculate the maximum number of regions using the NIM multiplication principle
    int regions = (int)Math.pow(2, N);
    return regions;
}

public static int maxRegions(int N) {
    // Calculate the maximum number of regions by iterating
    // through the possible values of N from 1 to 2N-3.
    int maxRegions = 0;
    for (int n = 1; n <= 2 * N - 3; n++) {
        // Calculate the number of regions by dividing the
        // area of the largest triangle possible into N triangles.
        double area = (n * (n - 1) / 2) * (n * (n + 1) / 2 * (n + 1) / 3);
        maxRegions = Math.max(maxRegions, (int)Math.ceil(area / N));
    }
    return maxRegions;
}

public static int maxRegions(int N) {
    int result = 0;

    if (N == 0) {
        // Base case: no regions
        return result;
    } else if (N == 1) {
        // Base case: one region
        return 1;
    }

    // Recursive case: divide the plane into two regions and place a triangle in each region
    result = maxRegions(N - 1) + 2;

    return result;
}

