public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Step 1: Create a graph instance
    Graph<int> graph = new Graph<int>(n);

    // Step 2: Add vertices and edges to the graph
    for (int[] path : paths) {
        graph.addEdge(path[0], path[1]);
    }

    // Step 3: Perform a DFS traversal to check if there is a path from the starting n-intersection to the ending n-intersection
    return graph.DFS(start[0], start[1], end[0], end[1]) ? "can be travelled" : "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

    // Create an adjacency matrix to represent the paths between n-intersections
    boolean[][] adjacencyMatrix = new boolean[n][n];
    for (int[] path : paths) {
        adjacencyMatrix[path[0]][path[1]] = true;
        adjacencyMatrix[path[1]][path[0]] = true;
    }

    // Create a queue to keep track of the n-intersections to be visited
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Create a set to keep track of the visited n-intersections
    Set<int[]> visited = new HashSet<>();

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        int[] current = queue.remove();

        // If the current n-intersection is the ending n-intersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Add unvisited adjacent n-intersections to the queue and mark them as visited
        for (int i = 0; i < n; i++) {
            if (adjacencyMatrix[current[0]][i] && !visited.contains(i)) {
                queue.add(new int[] {i});
                visited.add(i);
            }
        }
    }

    // If the queue is empty and no path was found, return "cannot be travelled"
    return "cannot be travelled";
}

