    // Create a queue to store n-tersections to visit
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection
        int[] current = queue.poll();

        // Check if current equals end
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Get the 8 n-tersections adjacent to current
        int[][] adjacent = {{current[0] - 1, current[1]}, {current[0] + 1, current[1]}, {current[0], current[1] - 1}, {current[0], current[1] + 1}, {current[0] - 1, current[1] - 1}, {current[0] + 1, current[1] - 1}, {current[0] - 1, current[1] + 1}, {current[0] + 1, current[1] + 1}};

        // Loop through each adjacent n-tersection
        for (int[] adj : adjacent) {
            // Check if adj is within the n-teresting space
            if (adj[0] < 0 || adj[0] >= n || adj[1] < 0 || adj[1] >= n) {
                continue;
            }

            // Check if adj is already visited
            if (visited.contains(adj)) {
                continue;
            }

            // Add adj to the list of visited n-tersections
            visited.add(adj);

            // Add adj to the queue to visit
            queue.add(adj);
        }
    }

    // If we reach this point, we have visited all the n-tersections and do not have a path to the end
    return "cannot be travelled";
}

