}

public double trimMean(int[] arr) {
  // sort the array in ascending order
  Arrays.sort(arr);

  // calculate the smallest 5% and largest 5% of the elements
  int smallest5 = (int) (arr.length * 0.05);
  int largest5 = (int) (arr.length * 0.05);

  // sum up the elements beyond the smallest 5% and largest 5%
  int sum = 0;
  for (int i = smallest5; i < arr.length - largest5; i++) {
    sum += arr[i];
  }

  // calculate the mean
  double mean = (double) sum / (arr.length - 2 * (smallest5 + largest5));

  // round the result to 5 decimal places
  return BigDecimal.valueOf(mean).setScale(5, RoundingMode.HALF_UP).doubleValue();
}

public static double trimMean(int[] arr) {
    int sum = 0;
    for (int value : arr) {
        sum += value;
    }
    int size = arr.length;
    int low = (int) (size * 0.05);
    int high = (int) (size - low);
    int min = Integer.MAX_VALUE;
    int max = Integer.MIN_VALUE;
    for (int i = 0; i < low; i++) {
        int value = arr[i];
        if (min > value) min = value;
    }
    for (int i = high; i < size; i++) {
        int value = arr[i];
        if (max < value) max = value;
    }
    int sumLow = 0;
    int sumHigh = 0;
    for (int i = 0; i < low; i++) {
        sumLow += arr[i] - min;
    }
    for (int i = high; i < size; i++) {
        sumHigh += arr[i] - max;
    }
    double meanLow = (double) sumLow / low;
    double meanHigh = (double) sumHigh / (size - low);
    double mean = (double) sum / size;
    double errorLow = Math.abs(mean - meanLow);
    double errorHigh = Math.abs(mean - meanHigh);
    if (errorLow < errorHigh) {
        return meanLow;
    } else {
        return meanHigh;
    }
}

public double trimMean(int[] arr) {
    // Find the smallest and largest values in the array
    int smallest = Integer.MAX_VALUE;
    int largest = Integer.MIN_VALUE;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < smallest) {
            smallest = arr[i];
        }
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    // Calculate the total sum of the remaining values
    double sum = 0.0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] != smallest && arr[i] != largest) {
            sum += arr[i];
        }
    }

    // Calculate the mean of the remaining values
    double mean = sum / (arr.length - 2);

    return mean;
}

