}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int half = n / 2;
    int[] sums = new int[half];
    for (int i = 0; i < half; i++) {
        sums[i] = arr[i] + arr[n - i - 1];
    }
    for (int sum : sums) {
        if (sum % k != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    Set<Integer> divisors = new HashSet<>();
    int sum = 0;
    for (int a : arr) {
        sum += a;
        if (a % k == 0) {
            divisors.add(a);
        }
    }
    if (sum % k != 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 == 1 && divisors.size() < n / 2) {
        return false;
    }
    int pairs = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int r = arr[i] + arr[j];
            if (r % k == 0 && divisors.contains(r)) {
                pairs++;
                if (pairs >= n / 2) {
                    return true;
                }
            }
        }
    }
    return false;
}

