  for ( int i = 0; i < arr.length; i++ ) {
    if ( map.containsKey(arr[i]) ) return false;
    map.put(arr[i], i);
  }
  for ( int i = 0; i < arr.length / 2; i++ ) {
    if ( map.containsKey(arr[i] + k) ) return true;
    if ( map.containsKey(k - arr[i]) ) return true;
  }
  return false;
}

public boolean canArrange(int[] arr, int k) {
    // Initialize variables
    int n = arr.length;
    int sum = 0;
    int divCount = 0;

    // Calculate the sum of the array elements
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }

    // Check if the sum is divisible by k
    if (sum % k != 0) {
        return false;
    }

    // Divide the sum by k and check if the result is even
    if ((sum / k) % 2 != 0) {
        return false;
    }

    // Divide the array into pairs
    for (int i = 0; i < n; i++) {
        int pairSum = arr[i] - arr[n - i - 1];
        if (pairSum % k == 0) {
            divCount++;
        }
    }

    // Check if the number of divisible pairs is equal to n/2
    return divCount == n / 2;
}

