int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 1) {
        return 0;
    }
    int[] dist = new int[n];
    for (int i = 0; i < n; i++) {
        dist[i] = -1;
    }
    dist[0] = 0;
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int i = 0; i < edges.length; i++) {
            if (edges[i][0] == node && dist[edges[i][1]] == -1) {
                dist[edges[i][1]] = dist[node] + 1;
                queue.offer(edges[i][1]);
            }
        }
    }
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (dist[i] == -1 || (!hasApple[i] && dist[i] == 0)) {
            continue;
        }
        minTime = Math.max(minTime, dist[i]);
    }
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Step 1: Create a graph from the input
  //nodes
  Node[] nodes = new Node[n];
  for (int i = 0; i < n; i++) {
    nodes[i] = new Node(i, hasApple[i]);
  }

  //edges
  for (int[] edge : edges) {
    int node1 = edge[0];
    int node2 = edge[1];
    Node node1Obj = nodes[node1];
    Node node2Obj = nodes[node2];
    node1Obj.neighbors.add(node2Obj);
    node2Obj.neighbors.add(node1Obj);
  }

  // Step 2: Perform DFS on the graph and keep track of the minimum time
  // to collect all apples
  int minTime = 0;
  boolean[] visited = new boolean[n];
  dfs(nodes[0], visited, nodes, 0, 0, true);

  // Step 3: Return the minimum time required to collect all apples
  return minTime;
}

private void dfs(Node node, boolean[] visited, Node[] nodes, int currTime, int timeSpent, boolean beingCollected) {
  // Step 1: Mark current node as visited and update the minimum time
  visited[node.index] = true;
  if (beingCollected) {
    minTime = Math.min(minTime, currTime);
  }

  // Step 2: Perform DFS on the neighbors
  for (Node neighbor : node.neighbors) {
    if (!visited[neighbor.index]) {
      dfs(neighbor, visited, nodes, currTime + 1, timeSpent, beingCollected || neighbor.hasApple);
    }
  }
}

