public int minTime(int n, int[][] edges, boolean[] hasApple) {
  int[] dist = new int[n];
  boolean[] visited = new boolean[n];

  for (int i = 0; i < n; i++) {
    dist[i] = Integer.MAX_VALUE;
  }

  Queue<Integer> queue = new LinkedList<>();
  queue.offer(0);
  dist[0] = 0;
  visited[0] = true;

  while (!queue.isEmpty()) {
    int curr = queue.poll();
    if (hasApple[curr]) {
      return dist[curr];
    }

    for (int i = 0; i < edges.length; i++) {
      int neighbor = edges[i][curr];
      if (neighbor == curr) {
        continue;
      }

      if (!visited[neighbor]) {
        visited[neighbor] = true;
        queue.offer(neighbor);
        dist[neighbor] = Math.min(dist[neighbor], dist[curr] + 1);
      }
    }
  }

  return dist[n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
   Set<Integer> visited = new HashSet<>();
   Queue<Integer> queue = new LinkedList<>();
   int time = 0;

   // Add the starting node to the queue
   queue.add(0);

   // Mark the starting node as visited
   visited.add(0);

   while (!queue.isEmpty()) {
       int current = queue.poll();
       time++;

       // If the current node has an apple, return the current time
       if (hasApple[current]) {
           return time;
       }

       // Add all the neighbors to the queue that haven't been visited yet
       for (int neighbor : edges[current]) {
           if (!visited.contains(neighbor)) {
               queue.add(neighbor);
               visited.add(neighbor);
           }
       }
   }

   // If we reach here, then we couldn't find an apple, so return 0
   return 0;
}

