public static String sortString(String s) {
        if (s.length() == 0) return "";

        char[] array = s.toCharArray();
        char[] result = new char[s.length()];

        int i = 0; // result index
        char lastChar = array[0]; // last character appended

        while (i < result.length) {
            // find the smallest character that is greater than lastChar
            char smallest = lastChar;
            while (smallest == lastChar) {
                smallest = array[++i];
            }
            result[i] = smallest;
            lastChar = smallest;
            i++;

            // find the largest character that is smaller than lastChar
            char largest = lastChar;
            while (largest == lastChar) {
                largest = array[--i];
            }
            result[i] = largest;
            lastChar = largest;
            i--;
        }

        return new String(result);
    }

public String sortString(String s) {
    char[] arr = s.toCharArray();
    Arrays.sort(arr);
    String result = "";
    int index = 0;
    while (index < arr.length) {
        char smallest = arr[index];
        int smallestCount = 1;
        while (index + 1 < arr.length && arr[index + 1] == smallest) {
            smallestCount++;
            index++;
        }
        result += smallest;
        index += smallestCount;
        char largest = arr[arr.length - 1];
        int largestCount = 1;
        while (arr.length - 2 >= 0 && arr[arr.length - 2] == largest) {
            largestCount++;
            arr.length--;
        }
        result += largest;
        arr.length -= largestCount;
    }
    return result;
}

public static String sortString(String s) {
    StringBuilder result = new StringBuilder();
    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    for (int i = 0; i < chars.length; i++) {
        char currentChar = chars[i];
        if (currentChar > result.charAt(result.length() - 1)) {
            while (i < chars.length - 1 && chars[i + 1] == currentChar) {
                i++;
            }
            result.append(currentChar);
        }
    }

    for (int i = 0; i < chars.length; i++) {
        char currentChar = chars[i];
        if (currentChar < result.charAt(result.length() - 1)) {
            while (i < chars.length - 1 && chars[i + 1] == currentChar) {
                i++;
            }
            result.append(currentChar);
        }
    }

    return result.toString();
}

