public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;
    int leftSum = 0;
    int rightSum = 0;
    for (int i = 0; i < nums.length; i++) {
        if (leftSum == average) {
            rightSum += nums[i];
        } else if (rightSum == average) {
            leftSum += nums[i];
        } else {
            leftSum += nums[i];
            rightSum += nums[nums.length - 1 - i];
        }
    }
    return leftSum == rightSum && leftSum == average;
}

public static boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int avg = sum / 2;
    int target = 0;
    for (int num : nums) {
        if (num == avg) {
            target++;
        }
    }
    for (int i = 0; i < nums.length - target; i++) {
        int sum1 = 0;
        for (int j = 0; j < i; j++) {
            sum1 += nums[j];
        }
        int sum2 = sum - sum1;
        if (sum2 == avg * (target - i)) {
            return true;
        }
    }
    return false;
}

