public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        sum += nums[i];
    }

    int average = sum / nums.length;
    int leftSum = 0;
    int rightSum = 0;

    for (int i = 0; i < nums.length; i++) {
        if (leftSum == average) {
            return true;
        }
        if (rightSum == average) {
            return true;
        }

        if (leftSum < average && nums[i] > average - leftSum) {
            leftSum += nums[i];
        } else if (rightSum < average && nums[i] > average - rightSum) {
            rightSum += nums[i];
        } else {
            return false;
        }
    }

    return leftSum == average || rightSum == average;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int avg = sum / nums.length;

    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
        if (leftSum == avg) {
            return true;
        }
    }

    int rightSum = sum - leftSum;
    for (int i = nums.length / 2; i < nums.length; i++) {
        rightSum += nums[i];
        if (rightSum == avg) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    for (int i = 1; i < cost.length; i++) {
        minCost += Math.min(cost[i - 1], cost[i]);
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int[] memo = new int[cost.length];
    memo[0] = cost[0];
    memo[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        int minCost = Math.min(memo[i - 1], memo[i - 2]) + cost[i];
        memo[i] = minCost;
    }

    return Math.min(memo[cost.length - 1], memo[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
