public boolean hasAllCodes(String s, int k) {
    // Check if the input string and substring length are valid
    if (s == null || k < 1 || k > s.length()) {
        return false;
    }

    // Check if every binary string of length k is a substring of s
    for (int i = 0; i < (1 << k); i++) {
        String binStr = Integer.toBinaryString(i);
        while (binStr.length() < k) {
            binStr = "0" + binStr;
        }
        if (!s.contains(binStr)) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    for (int i = 0; i < (1 << k); i++) {
        if (!s.contains(Integer.toBinaryString(i))) {
            return false;
        }
    }
    return true;
}

