public int minInsertions(String s) {
  int left = 0, right = 0;
  for (char c : s.toCharArray()) {
    if (c == '(') {
      left++;
    } else {
      right++;
    }
  }

  int min = Math.min(left, right);

  for (char c : s.toCharArray()) {
    if (c == '(') {
      left--;
    } else {
      right--;
    }
    min = Math.min(min, Math.min(left, right));
    if (left == 0 && right == 0) {
      break;
    }
  }

  return min;
}

