    int left = 0, right = 0, min = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') left++;
        else if (c == ')') right++;
        min = Math.max(min, left - right);
    }
    return Math.min(min, left) + right;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (arr[0] != arr[n - 1]) {
        int x = 0, y = n - 1;
        while (arr[x] != arr[y]) {
            if (arr[x] > arr[y]) {
                x++;
            } else {
                y--;
            }
        }
        arr[x] -= 1;
        arr[y] += 1;
        minOperations++;
    }
    return minOperations;
}

