public static int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return 1;
    }

    int[] fib = {1, 1, 2};
    int sum = 2;

    while (sum <= k) {
        fib = Arrays.copyOf(fib, fib.length + 1);
        fib[fib.length - 1] = fib[fib.length - 2] + fib[fib.length - 3];
        sum += fib[fib.length - 1];
    }

    return fib.length - 2;
}

public int findMinFibonacciNumbers(int k) {
    if (k < 2) {
        return k;
    }

    // Initialize the Fibonacci sequence and the current sum to 0
    int[] fibonacci = new int[k];
    fibonacci[0] = 1;
    fibonacci[1] = 1;
    int currentSum = 2;

    // Iterate over the Fibonacci sequence until the current sum is less than or equal to k
    for (int i = 2; currentSum <= k; i++) {
        // Add the current Fibonacci number to the sequence
        fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];

        // Update the current sum
        currentSum += fibonacci[i];
    }

    return i - 1;
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[] {1, 1};
    int n = 2;
    while (fib[n - 1] + fib[n - 2] <= k) {
        fib[n++] = fib[n - 1] + fib[n - 2];
    }
    return n - 1;
}

public int findMinFibonacciNumbers(int k) {
    // Initialize the Fibonacci sequence with the first two numbers.
    int fib1 = 1;
    int fib2 = 1;
    int index = 2;

    // Loop until the total sum of the Fibonacci numbers is greater than or equal to k.
    while (fib1 + fib2 < k) {
        // Calculate the next Fibonacci number.
        int fib = fib1 + fib2;

        // Update the Fibonacci sequence and the index.
        fib1 = fib2;
        fib2 = fib;
        index++;
    }

    // Return the minimum number of Fibonacci numbers needed to sum up to k.
    return index;
}

public int findMinFibonacciNumbers(int k) {
  if (k <= 1) {
      return 1;
  }
  int[] fib = new int[] {1, 1}; // initialize Fibonacci sequence with first 2 values
  int i = 2; // index of next Fibonacci number to add to sequence
  while (i < k) {
      fib[i] = fib[i - 1] + fib[i - 2]; // calculate next Fibonacci number
      i++;
  }
  int count = 0;
  while (k > 0) {
      if (k >= fib[i - 1]) {
          count++;
          k -= fib[i - 1];
      } else {
          i--;
      }
  }
  return count;
}

