    for (int i = 1; i * i <= n; i++) {
        // Check if i divides n evenly
        if (n % i == 0) {
            // Add i to the list of factors
            factors.add(i);

            // If i is not the square of a number, add n / i to the list as well
            if (i * i != n) {
                factors.add(n / i);
            }
        }
    }

