public int maxUniqueSplit(String s) {
    // Initialize variables to keep track of the maximum number of unique substrings and the current substring
    int maxUniqueSubstrings = 0;
    StringBuilder currentSubstring = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);

        // If the current character is already in the current substring, skip it
        if (currentSubstring.indexOf(currentChar) != -1) {
            continue;
        }

        // Add the current character to the current substring
        currentSubstring.append(currentChar);

        // If the length of the current substring is greater than the maximum, update the maximum
        if (currentSubstring.length() > maxUniqueSubstrings) {
            maxUniqueSubstrings = currentSubstring.length();
        }
    }

    // Return the maximum number of unique substrings
    return maxUniqueSubstrings;
}

