public int minOperations(String[] logs) {
    // Keep track of the current folder depth
    int depth = 0;

    // Iterate through the logs
    for (String log : logs) {
        // If the log is a forward directory, increase the depth
        if (log.startsWith("d")) {
            depth++;
        // If the log is a backward directory, decrease the depth
        } else if (log.startsWith("..")) {
            depth = Math.max(depth - 1, 0);
        }
    }

    return depth; 
}

