public int minOperations(String[] logs) {
    int minOps = 0;

    for (String log : logs) {
        // Skip the "./" operation, which has no effect on the current folder
        if (log.equals("./")) {
            continue;
        }

        // For "../" and "dX/" operations, decrement the minimum number of operations
        if (log.startsWith("../") || log.startsWith("d")) {
            minOps--;
        }

        // For "dX/" operations, increment the minimum number of operations
        if (log.startsWith("d")) {
            minOps++;
        }
    }

    return minOps;
}

public String getSmallestString(int n, int k) {
    // Initialize the result string with the correct length
    StringBuilder result = new StringBuilder(n);

    // Initialize the current value and the current position
    int currentValue = 0;
    int currentPosition = 0;

    // Loop through each character in the string
    for (int i = 0; i < n; i++) {
        // Get the value of the current character
        int charValue = (int) Math.pow('a', currentPosition) + currentValue - 1;

        // Check if the current character is the smallest possible character
        if (charValue < k) {
            // If it is, set the current character to the smallest possible character
            result.append((char) charValue);

            // Update the current value and position
            currentValue = charValue + 1;
            currentPosition++;
        } else {
            // If it's not, set the current character to the smallest possible character
            // that is greater than or equal to the current value
            result.append((char) (k - (currentValue - 1)));

            // Update the current value and position
            currentValue = k;
            currentPosition++;
        }
    }

    return result.toString();
}

