public String getSmallestString(int n, int k) {
    if (k < 1 || k > (n * 26)) {
        throw new IllegalArgumentException("Invalid input: k out of range");
    }
    char[]result = new char[n];
    int alphabetSize = 26;
    int remainder = k;
    int pos = 0;
    while (pos < n) {
        int charIndex = remainder % alphabetSize;
        remainder = remainder / alphabetSize;
        result[pos] = (char)(charIndex + 'a');
        pos++;
    }
    return new String(result);
}

