public static double calculateProbability(int n) {
  if (n < 2) {
    // There is only 1 passenger, so the probability is 1
    return 1.0;
  }
  // Calculate the probability that each passenger sits in their own seat
  double[] probabilities = new double[n];
  for (int i = 0; i < n; i++) {
    probabilities[i] = (double) (n - i - 1) / (n - 1);
  }
  // Calculate the probability that the last passenger sits in their own seat
  double probability = 1.0;
  for (double p : probabilities) {
    probability *= p;
  }
  return probability;
}

