private static boolean checkSteppingNumber(int num) {
        if (num == 0) {
            return true;
        }

        int prevDigit = 0;
        char[] digits = String.valueOf(num).toCharArray();

        for (int i = 0; i < digits.length; i++) {
            char digit = digits[i];
            if (prevDigit == 0) {
                prevDigit = digit - '0';
                continue;
            }

            int currDigit = digit - '0';
            if (Math.abs(prevDigit - currDigit) != 1) {
                return false;
            }

            prevDigit = currDigit;
        }

        return true;
    }

