        // If the sorted array has only one element, return 1
        if (A.length == 1) {
            return 1;
        }

        // If the sorted array has two elements, check if the sum of the two elements is a perfect square
        if (A.length == 2) {
            if (isPerfectSquare(A[0] + A[1])) {
                return 2;
            }
            return 1;
        }

        // Initialize a set to store unique permutations
        Set<Integer> uniquePermutations = new HashSet<>();

        // Initialize the first element of the sorted array as the first element of the unique permutation
        int current = A[0];
        uniquePermutations.add(current);

        // Loop through the remaining elements of the sorted array
        for (int i = 1; i < A.length; i++) {
            // If the sum of the current element and the next element is a perfect square, add the current element to the unique permutation
            if (isPerfectSquare(current + A[i])) {
                uniquePermutations.add(current);
                current = current + A[i];
            } else {
                // If the sum of the current element and the next element is not a perfect square, add the next element to the unique permutation
                current = current + A[i];
            }
        }

        // Return the size of the unique permutations set
        return uniquePermutations.size();
