        while (num > 0) {
            digitSum += num % 10;
            num /= 10;
        }
        if (digitSum == (i % 10) * 2 + 1) {
            result.add(Integer.toString(i));
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> numbers = new ArrayList<>();

    // Generate the center symmetric numbers of length n
    for (int i = 0; i < n; i++) {
        // Get the prefix and suffix characters
        char prefix = (char) ('0' + i);
        char suffix = (char) ('0' + (n - i - 1));

        // Construct the center symmetric number
        String number = prefix + "1" + suffix;

        // Add the number to the list
        numbers.add(number);
    }

    return numbers;
}

