private static boolean isCenterSymmetric(String num, int n) {
    for (int i = 0; i < n / 2; i++) {
        if (num.charAt(i) != num.charAt(n - i - 1)) {
            return false;
        }
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the points are in a counterclockwise order
    int determinant = crossProduct(points[0], points[1], points[2]);
    if (determinant > 0) {
        return true;
    } else if (determinant == 0) {
        return false;
    }

    // Check if the points are collinear
    determinant = crossProduct(points[1], points[2], points[0]);
    if (determinant == 0) {
        return false;
    }

    // Check if the points are in a clockwise order
    determinant = crossProduct(points[2], points[1], points[0]);
    if (determinant > 0) {
        return false;
    }

    return true;
}

public static int crossProduct(int[] vector1, int[] vector2) {
    return vector1[0] * vector2[1] - vector1[1] * vector2[0];
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int x1 = points[0][0] - points[1][0];
    int y1 = points[0][1] - points[1][1];
    int x2 = points[1][0] - points[2][0];
    int y2 = points[1][1] - points[2][1];
    int x3 = points[2][0] - points[0][0];
    int y3 = points[2][1] - points[0][1];
    return x1 * y2 - y1 * x2 == x2 * y3 - y2 * x3 && x1 * y3 - y1 * x3 == x3 * y1 - y3 * x1;
}

public static boolean isBoomerang(int[][] points) {
    // Sort the points by their x-coordinate
    Arrays.sort(points, Comparator.comparingInt(point -> point[0]));

    // Calculate the distance between the first and last points
    int dist1 = distance(points[0][0], points[0][1], points[points.length - 1][0], points[points.length - 1][1]);

    // Calculate the distance between the second and last-but-one points
    int dist2 = distance(points[1][0], points[1][1], points[points.length - 2][0], points[points.length - 2][1]);

    // Check if the distances are different
    return dist1 != dist2;
}

private static int distance(int x1, int y1, int x2, int y2) {
    return (int) Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
}

public static boolean isBoomerang(int[][] points) {
    //calculate the determinant of the two vectors formed by points 1 and 2, and 1 and 3
    int determinant1 = points[1][0] * points[2][1] - points[1][1] * points[2][0];
    int determinant2 = points[0][0] * points[2][1] - points[0][1] * points[2][0];

    //if the determinants of the two vectors have different signs, the flag is set to true
    boolean flag = false;
    if ((determinant1 > 0 && determinant2 < 0) || (determinant1 < 0 && determinant2 > 0)) {
        flag = true;
    }

    return flag;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The array should contain exactly 3 points.");
    }

    int x0 = points[0][0];
    int y0 = points[0][1];
    int x1 = points[1][0];
    int y1 = points[1][1];
    int x2 = points[2][0];
    int y2 = points[2][1];

    return (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0) != 0;
}

public static int findNthUglyNumber(int n) {
  if (n <= 0) {
    throw new IllegalArgumentException("n must be positive.");
  }

  // Initialize the queue with the first 10 numbers.
  Queue<Integer> queue = new LinkedList<>();
  for (int i = 0; i < 10; i++) {
    queue.offer(i);
  }

  // Keep track of the number of elements in the queue and the first index.
  int count = 1;
  int first = 0;

  // Loop until we have enough elements in the queue.
  while (count < n) {
    // Get the first element in the queue.
    int current = queue.peek();

    // If the current element is a palindrome, we can remove it.
    if (current == String.valueOf(current).reverse().toString()) {
      queue.poll();
      count--;
    }

    // If the current element is not a palindrome, we need to add its mirror.
    else {
      queue.offer(String.valueOf(current).reverse().toString());
      count++;
    }
  }

  // Return the first nth element in the queue.
  return queue.peek();
}

public static int findNthUglyNumber(int n) {
    int i = 0, j = 0, k = 0;
    int[] factors = new int[] {2, 3, 5};
    int[] factorsMultiplier = new int[] {1, 1, 1};
    int[] uglyNumbers = new int[n];

    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
      int min = Integer.MAX_VALUE;

      for (int factor = 0; factor < factors.length; factor++) {
        int factorValue = factors[factor] * factorsMultiplier[factor];

        if (factorValue < min && uglyNumbers[i - 1] == factorValue) {
          min = factorValue;
          factorsMultiplier[factor]++;
        }
      }

      uglyNumbers[i] = min;
    }

    return uglyNumbers[n - 1];
  }

public static int findNthUglyNumber(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    // Initialize a queue to store the ugly numbers
    Queue<Integer> queue = new LinkedList<>();

    // Enqueue the first element
    queue.offer(1);

    // Loop until the queue size is equal to n
    while (queue.size() < n) {
        // Dequeue the current element
        int current = queue.poll();

        // Enqueue each of its multiples of 2, 3, and 5
        queue.offer(current * 2);
        queue.offer(current * 3);
        queue.offer(current * 5);
    }

    // Return the nth element in the queue
    return queue.peek();
}

public static int findNthUglyNumber(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] factors = new int[] {2, 3, 5}; // 2, 3, and 5 are the prime factors of the ugly numbers
    List<Integer> uglyNumbers = new ArrayList<Integer>(); // initialize an empty list to store the ugly numbers
    uglyNumbers.add(1); // add 1 as the first ugly number

    for (int i = 1; i < n; i++) {
        // find the next ugly number by considering the product of the prime factors
        int nextUglyNumber = Integer.MAX_VALUE; // initialize with a large number
        for (int factor : factors) {
            nextUglyNumber = Math.min(nextUglyNumber, uglyNumbers.get(i - 1) * factor);
        }
        uglyNumbers.add(nextUglyNumber);
    }

    return uglyNumbers.get(n - 1); // return the nth ugly number
}

