public static int calculateEnergy(String s) {
    int max = 0;
    for (int i = 0; i < s.length(); i++) {
        int start = i;
        while (i < s.length() && s.charAt(i) == s.charAt(start)) {
            i++;
        }
        max = Math.max(max, i - start);
    }
    return max;
}

public static int calculateEnergy(String s) {
    // Keep track of the longest non-empty substring
    // containing only one character's length
    int longest = 0;

    // Keep track of the current substring's length
    int current = 0;

    // Iterate through the characters in the string
    for (int i = 0; i < s.length(); i++) {
        // If the current character is the same as the previous character,
        // increase the current substring's length by 1
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        }
        // If the current character is not the same as the previous character,
        // set the current substring's length to 1
        else {
            current = 1;
        }

        // Update the longest substring's length if necessary
        if (current > longest) {
            longest = current;
        }
    }

    // Return the energy of the string
    return longest;
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() < 1) {
        return 0;
    }
    int maxLen = 0, currentLen = 1;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
            currentChar = s.charAt(i);
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static int calculateEnergy(String s) {
        if (s.length() <= 0) return 0;

        String longestNonEmptySubstring = "";
        int currentLength = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i+1)) {
                currentLength++;
                if (currentLength > longestNonEmptySubstring.length()) {
                    longestNonEmptySubstring = s.charAt(i) + ""; // This will append the char at index i to the string.
                }
            } else {
                currentLength = 0;
            }
        }
        return longestNonEmptySubstring.length();
    }

public static int calculateEnergy(String s) {
      if (s.length() == 0) {
          return 0;
      }

      int max = 0, start = 0, end = 0;
      for (int center = 0; center < s.length(); center++) {
          int i = center, j = center + 1;
          int halfLen = 0;
          while (i >= 0 && j < s.length() && s.charAt(i) == s.charAt(j)) {
              halfLen++;
              i--;
              j++;
          }
          int currentLength = halfLen * 2;
          if (currentLength > max) {
              max = currentLength;
              start = center - halfLen + 1;
              end = center + halfLen;
          }
      }

      return end - start + 1;
  }

