public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - (i * i);
        if (remainder == 0) {
            count++;
        } else {
            count += 2;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
  int count = 0;
  for (int i = 1; i * i <= n; i++) {
    while (n >= i) {
      count++;
      n -= i;
    }
  }
  return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            count++;
            n -= i;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0, x = 1;

    while (n > 0) {
        if (x * x <= n) {
            n -= x * x;
            count++;
        } else {
            x++;
        }
    }

    return count;
}

public static int minPerfectSquareSum(int n) {
    HashMap<Integer, Integer> squareMap = new HashMap<Integer, Integer>(); // Map to store squares and their counts
    for (int i = 1; i * i <= n; i++) { // Loop through perfect squares
        if (n < i * i) { // If the target is already smaller than the current square, we can stop the loop
            break;
        }
        int count = squareMap.getOrDefault(i * i, 0) + 1; // Increment the count for the current square
        squareMap.put(i * i, count); // Update the map with the current square and count
        n -= i * i; // Reduce the target by the current square
    }
    if (n > 0) { // If there are still remaining numbers in the target, we cannot form any perfect square sum
        return -1;
    }
    int minCount = Integer.MAX_VALUE; // Initialize the minimum count with the maximum integer value
    for (int count : squareMap.values()) { // Loop through the counts in the map
        if (count < minCount) { // Update the minimum count if the current count is smaller than the previous minimum
            minCount = count;
        }
    }
    return minCount; // Return the minimum count
}

public static String reverseWords(String s) {
    // Split the input string into an array of words
    String[] words = s.split(" ");

    // Initialize the output string with an empty string
    String output = "";

    // Loop through each word in the array
    for (String word : words) {
        // Initialize a new StringBuilder to store the reversed word
        StringBuilder reversedWord = new StringBuilder();

        // Loop through each character of the word
        for (int i = word.length() - 1; i >= 0; i--) {
            // Append the current character to the reversed word
            reversedWord.append(word.charAt(i));
        }

        // Append the reversed word to the output string, separated by a space
        output += reversedWord.toString() + " ";
    }

    // Return the output string with the reversed words
    return output.trim();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        reversedSentence.append(reversedWord.toString());
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}

